#include "stdlib/complex/float32/base/sub.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/reim.h"

/**
* Subtracts two single-precision complex floating-point numbers.
*
* @param z1       input value
* @param z2       input value
* @return         result
*
* @example
* #include "stdlib/complex/float32/ctor.h"
* #include "stdlib/complex/float32/real.h"
* #include "stdlib/complex/float32/imag.h"
*
* stdlib_complex64_t z1 = stdlib_complex64( 5.0f, 3.0f );
*
* stdlib_complex64_t z2 = stdlib_complex64( -2.0f, 1.0f );
*
* stdlib_complex64_t out = stdlib_base_complex64_sub( z1, z2 );
*
* float re = stdlib_complex64_real( out );
* // returns 7.0f
*
* float im = stdlib_complex64_imag( out );
* // returns 2.0f
*/
stdlib_complex64_t stdlib_base_complex64_sub( const stdlib_complex64_t z1, const stdlib_complex64_t z2 ) {
	float re1;
	float re2;
	float im1;
	float im2;
	float re;
	float im;

	stdlib_complex64_reim( z1, &re1, &im1 );
	stdlib_complex64_reim( z2, &re2, &im2 );

	re = re1 - re2;
	im = im1 - im2;

	return stdlib_complex64( re, im );
}","lineStart":1,"lineEnd":62,"totalLines":62,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-base-sub/src/main.c","time":{"start":1783262896830,"end":1783262896853}},"id":"prt_f32c061cd001qqIyF3jOU34WFy","sessionID":"ses_0cd3fce52ffeK3X4CsyA2aedMi","messageID":"msg_f32c0545e001eJZ58iemsnKvWf"}}

